#!/bin/sh
# Name: MagicAds
# Icon: data:image/png;base64,
# Author: Dochoithuvi
# Version: 1.2.0 FINAL
# MagicAds - Vietnamese ASCII edition
# License source: DCPRO GhostGuard signed online registry
# Policy: online license check when enabling; disabling is always allowed.
# 1.2.0 FINAL: robust DB verification + one-time diagnostic settle; no permanent polling.
# Field-tested: PW3 5.16.2.1.1; PW4 5.18.1.1; PW5 5.19.2; Basic 2022 5.19.2/5.19.2.0.1; Basic 2024 5.17.1.0.4.

DB="/var/local/appreg.db"

REG_URL="https://raw.githubusercontent.com/dochoithuvi/ghostguard-kindle/main/licenses/licenses.json"
SIG_URL="https://raw.githubusercontent.com/dochoithuvi/ghostguard-kindle/main/licenses/licenses.sig"

PINNED_KEY_ID="ghostguard-prod-2026-08"

TMP_BASE="/tmp/magicads.$$"
REG_FILE="${TMP_BASE}.json"
SIG_FILE="${TMP_BASE}.sig.json"
PUB_FILE="${TMP_BASE}.pub.pem"
SIG_BIN="${TMP_BASE}.sig.bin"

cleanup() {
    rm -f "$REG_FILE" "$SIG_FILE" "$PUB_FILE" "$SIG_BIN" 2>/dev/null
}
trap cleanup EXIT HUP INT TERM

fail() {
    echo ""
    echo "MagicAds: $1"
    echo "MagicAds dung lai de bao ve he thong. Khong thuc hien them thay doi."
    exit 1
}

license_fail() {
    echo ""
    echo "MagicAds: $1"
    echo "Khong co license hop le. MagicAds se dung va KHONG thay doi he thong."
    exit 1
}

download_file() {
    url="$1"
    out="$2"

    if command -v curl >/dev/null 2>&1; then
        curl -L -f -sS --connect-timeout 8 --max-time 20 "$url" -o "$out" >/dev/null 2>&1
        return $?
    fi

    if command -v wget >/dev/null 2>&1; then
        wget -q -T 20 -O "$out" "$url" >/dev/null 2>&1
        return $?
    fi

    if command -v busybox >/dev/null 2>&1; then
        busybox wget -q -T 20 -O "$out" "$url" >/dev/null 2>&1
        return $?
    fi

    return 127
}

sha256_stdin() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum | awk '{print $1}'
        return
    fi

    if command -v busybox >/dev/null 2>&1 && busybox sha256sum </dev/null >/dev/null 2>&1; then
        busybox sha256sum | awk '{print $1}'
        return
    fi

    if command -v openssl >/dev/null 2>&1; then
        openssl dgst -sha256 2>/dev/null | sed 's/^.*= *//'
        return
    fi

    return 1
}

sha256_file() {
    file="$1"

    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$file" 2>/dev/null | awk '{print $1}'
        return
    fi

    if command -v busybox >/dev/null 2>&1 && busybox sha256sum </dev/null >/dev/null 2>&1; then
        busybox sha256sum "$file" 2>/dev/null | awk '{print $1}'
        return
    fi

    if command -v openssl >/dev/null 2>&1; then
        openssl dgst -sha256 "$file" 2>/dev/null | sed 's/^.*= *//'
        return
    fi

    return 1
}

echo "MagicAds PRO 1.2.0 FINAL"

# Neu PRO dang bat, cho phep go cai dat ngay ca khi mat mang/license het han.
# Khong bao gio de license lock chan duong rollback.
SKIP_LICENSE_CHECK=0
[ -f /var/local/magicads/enabled ] && SKIP_LICENSE_CHECK=1

if [ "$SKIP_LICENSE_CHECK" -eq 0 ]; then
echo "Dang kiem tra license tren GitHub..."

[ -r /proc/usid ] || license_fail "Khong doc duoc serial Kindle (/proc/usid)."

# Giong GhostGuard: xoa ky tu la, viet hoa, chi giu A-Z va 0-9.
SERIAL="$(cat /proc/usid 2>/dev/null | tr -cd 'A-Za-z0-9' | tr 'a-z' 'A-Z')"
[ -n "$SERIAL" ] || license_fail "Serial Kindle khong hop le."

SERIAL_HASH="$(printf '%s' "$SERIAL" | sha256_stdin)"
case "$SERIAL_HASH" in
    ????????????????????????????????????????????????????????????????) ;;
    *) license_fail "Kindle khong co cong cu SHA-256 phu hop." ;;
esac

download_file "$REG_URL" "$REG_FILE" || license_fail "Khong tai duoc danh sach license. Hay bat Wi-Fi va thu lai."
download_file "$SIG_URL" "$SIG_FILE" || license_fail "Khong tai duoc chu ky license. Hay bat Wi-Fi va thu lai."

[ -s "$REG_FILE" ] || license_fail "Danh sach license rong."
[ -s "$SIG_FILE" ] || license_fail "Du lieu chu ky license rong."

KEY_ID="$(sed -n 's/^[[:space:]]*"key_id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$SIG_FILE" | head -n 1)"
EXPECTED_SHA="$(sed -n 's/^[[:space:]]*"content_sha256"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$SIG_FILE" | head -n 1)"
SIG_B64="$(sed -n 's/^[[:space:]]*"sig"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$SIG_FILE" | head -n 1)"

[ "$KEY_ID" = "$PINNED_KEY_ID" ] || license_fail "Khoa license tren server da thay doi. Can cap nhat MagicAds."
[ -n "$EXPECTED_SHA" ] || license_fail "Khong doc duoc SHA-256 cua registry."

ACTUAL_SHA="$(sha256_file "$REG_FILE")"
[ -n "$ACTUAL_SHA" ] || license_fail "Khong tinh duoc SHA-256 cua registry."
[ "$ACTUAL_SHA" = "$EXPECTED_SHA" ] || license_fail "Registry license bi thay doi hoac hong."

# Neu Kindle co OpenSSL, kiem tra them chu ky RSA-SHA256 bang public key da ghim.
# Neu khong co OpenSSL, MagicAds van dung HTTPS + content_sha256 de tuong thich Kindle cu.
if command -v openssl >/dev/null 2>&1 && [ -n "$SIG_B64" ]; then
    cat > "$PUB_FILE" <<'MAGICADS_PUBKEY'
-----BEGIN PUBLIC KEY-----
MIIBojANBgkqhkiG9w0BAQEFAAOCAY8AMIIBigKCAYEA1ZixzeJ8w9dfVWSsx3AP
kTophnu2IsH9VYaCmsGqeCA4ffm1wayd6smC6c3kiVWWHTub3y2IdTS3ihveAh5O
N3+QkAdv+f/Jo7Y0xntmEdSgio/E4NM6DwZojXizulnUhAPEorsw3u32OopLc/wW
sq2b7mHj1X/n5y58TqBfgjs6fkVUGF+XZw+hsZphdPUSjCXbzxXQ6srSYKvFsbOL
0AowFZ60StSeYAhqXU1huk6khhMSXqbXG7cIqyPd2xPqpLTigL3r3fd661SHv0NS
gZ1gXSxWJTXi5RMmwo9CMujN0p7rkq0EEiW/kZfE236eqmEHJLQE9fEuaOA25Xhc
UlIiT8W4kLk/WaKb5lPrmaeydQk9ZkOddkrgcQmIPg9KStu7VDlCqadwDFgR+80w
afcF3WGU3bJVO6zWXuRgrZKmZXLySV3CnA/41BA5OH5f7X9M5WcphLv9/Z7XIZ31
6QqIt90T8mSMhar8f5a1FjnSzDNk6ud+QvRywXHLof7HAgMBAAE=
-----END PUBLIC KEY-----
MAGICADS_PUBKEY

    if printf '%s' "$SIG_B64" | openssl base64 -d -A > "$SIG_BIN" 2>/dev/null; then
        openssl dgst -sha256 -verify "$PUB_FILE" -signature "$SIG_BIN" "$REG_FILE" >/dev/null 2>&1 \
            || license_fail "Chu ky RSA cua registry khong hop le."
    else
        license_fail "Khong giai ma duoc chu ky RSA cua registry."
    fi
fi

# Tim entry theo serial_hash. serial_hash la truong dau cua moi entry.
ENTRY="$(sed -n "/\"serial_hash\"[[:space:]]*:[[:space:]]*\"$SERIAL_HASH\"/,/^[[:space:]]*}[,]*[[:space:]]*$/p" "$REG_FILE")"
[ -n "$ENTRY" ] || license_fail "Thiet bi nay chua co license tren GhostGuard."

STATUS="$(printf '%s\n' "$ENTRY" | sed -n 's/^[[:space:]]*"status"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
LICENSE_ID="$(printf '%s\n' "$ENTRY" | sed -n 's/^[[:space:]]*"license_id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
ISSUED_AT="$(printf '%s\n' "$ENTRY" | sed -n 's/^[[:space:]]*"issued_at"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"
EXPIRE="$(printf '%s\n' "$ENTRY" | sed -n 's/^[[:space:]]*"expire"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)"

[ "$STATUS" = "active" ] || license_fail "License khong o trang thai active."

printf '%s\n' "$ENTRY" | grep -q '"ghostguard"' || \
printf '%s\n' "$ENTRY" | grep -q '"ultimate"' || \
    license_fail "License khong co quyen ghostguard/ultimate."

TODAY="$(date +%Y-%m-%d 2>/dev/null)"
case "$TODAY" in
    ????-??-??) ;;
    *) license_fail "Ngay gio he thong Kindle khong hop le." ;;
esac

TODAY_NUM="$(printf '%s' "$TODAY" | tr -d '-')"
case "$TODAY_NUM" in
    *[!0-9]*|"") license_fail "Ngay gio he thong Kindle khong hop le." ;;
esac

if [ -n "$ISSUED_AT" ]; then
    ISSUE_NUM="$(printf '%s' "$ISSUED_AT" | tr -d '-')"
    case "$ISSUE_NUM" in
        *[!0-9]*|"") license_fail "Ngay cap license khong hop le." ;;
    esac
    [ "$TODAY_NUM" -ge "$ISSUE_NUM" ] || license_fail "License chua den ngay co hieu luc."
fi

EXPIRE_LOWER="$(printf '%s' "$EXPIRE" | tr 'A-Z' 'a-z')"
if [ "$EXPIRE_LOWER" != "lifetime" ]; then
    EXP_NUM="$(printf '%s' "$EXPIRE" | tr -d '-')"
    case "$EXP_NUM" in
        *[!0-9]*|"") license_fail "Ngay het han license khong hop le." ;;
    esac
    [ "$TODAY_NUM" -le "$EXP_NUM" ] || license_fail "License da het han."
fi

echo "License hop le: ${LICENSE_ID:-UNKNOWN}"
echo "Het han: ${EXPIRE:-UNKNOWN}"
echo "Cho phep chay MagicAds."
echo ""
else
    echo "MagicAds PRO dang bat: bo qua kiem tra online de cho phep go/rollback an toan."
    echo ""
fi


# ============================================================
# MagicAds PRO - persistent anti-ad guard
# ============================================================

PRO_DIR="/var/local/magicads"
PRO_MARKER="$PRO_DIR/enabled"
GUARD="$PRO_DIR/guard.sh"
GUARD_LOG="$PRO_DIR/guard.log"
BLOCK_ADUNITS="/var/local/adunits"
BLOCK_ASSETS="/mnt/us/.assets"
UPSTART_JOB="/etc/upstart/magicads-pro.conf"
SYSV_INIT="/etc/init.d/magicads-pro"
CRON_FILE="/etc/crontab/root"
CRON_TAG="# MAGICADS_PRO"

command -v sqlite3 >/dev/null 2>&1 || fail "Khong tim thay sqlite3."
[ -f "$DB" ] || fail "Khong tim thay /var/local/appreg.db."

# Mot so firmware/account state co the tam thoi khong co row adunit.viewable.
# UPDATE 0 row van tra rc=0, vi vay phai kiem tra row-count rieng.
db_adunit_count() {
    sqlite3 "$DB" 'select count(*) from properties where name = "adunit.viewable";' 2>/dev/null | tail -n 1 | tr -d '\r\n ' 
}

db_adunit_bad_count() {
    # NULL also counts as bad. The old query missed NULL because SQL NOT IN returns NULL.
    sqlite3 "$DB" 'select count(*) from properties where name = "adunit.viewable" and (value is null or lower(trim(cast(value as text))) not in ("false","0"));' 2>/dev/null | tail -n 1 | tr -d '\r\n '
}

db_force_false_main() {
    cnt="$(db_adunit_count)"
    case "$cnt" in
        ''|*[!0-9]*) return 3 ;;
        0) return 2 ;;
    esac
    # Give Amazon services a short chance to release a transient SQLite lock.
    sqlite3 "$DB" 'pragma busy_timeout=3000; update properties set value = "false" where name = "adunit.viewable";' >/dev/null 2>&1 || return 1
    bad="$(db_adunit_bad_count)"
    [ "$bad" = "0" ] || return 1
    return 0
}

db_diag_snapshot() {
    stage="$1"
    diag="$PRO_DIR/db_diag.log"
    mkdir -p "$PRO_DIR" >/dev/null 2>&1 || true
    {
        echo "=== $(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null) stage=$stage ==="
        echo "db=$DB"
        printf 'journal_mode='
        sqlite3 "$DB" 'pragma journal_mode;' 2>/dev/null | tail -n 1 || true
        printf 'row_count='
        db_adunit_count
        echo
        printf 'bad_count='
        db_adunit_bad_count
        echo
        sqlite3 "$DB" 'select "ROW|rowid="||rowid||"|type="||typeof(value)||"|value="||quote(value) from properties where name = "adunit.viewable" order by rowid;' 2>/dev/null || true
    } >> "$diag" 2>/dev/null
}

copy_db_diag_to_documents() {
    [ -f "$PRO_DIR/db_diag.log" ] || return 0
    [ -d /mnt/us/documents ] || return 0
    cp -f "$PRO_DIR/db_diag.log" /mnt/us/documents/MagicAds_DB.log >/dev/null 2>&1 || true
}

db_settle_verify() {
    # One-time activation diagnostic only: checkpoints at 0s, 1s, 3s and 10s.
    # No permanent polling and no battery cost after activation.
    stage="0s"
    delay="0"
    for item in "0:0s" "1:1s" "2:3s" "7:10s"; do
        delay="${item%%:*}"
        stage="${item#*:}"
        [ "$delay" = "0" ] || sleep "$delay"

        cnt="$(db_adunit_count)"
        case "$cnt" in
            ''|*[!0-9]*) db_diag_snapshot "${stage}_count_invalid"; return 1 ;;
            0) db_diag_snapshot "${stage}_row_absent"; continue ;;
            *)
                bad="$(db_adunit_bad_count)"
                case "$bad" in ''|*[!0-9]*) db_diag_snapshot "${stage}_bad_invalid"; return 1 ;; esac
                if [ "$bad" != "0" ]; then
                    db_diag_snapshot "${stage}_before_repair"
                    db_force_false_main || true
                fi
                db_diag_snapshot "${stage}_after_check"
                ;;
        esac
    done

    cnt="$(db_adunit_count)"
    case "$cnt" in
        ''|*[!0-9]*) return 1 ;;
        0) return 0 ;;
    esac
    [ "$(db_adunit_bad_count)" = "0" ]
}

root_rw() {
    if command -v mntroot >/dev/null 2>&1; then
        mntroot rw >/dev/null 2>&1 && return 0
    fi
    mount -o remount,rw / >/dev/null 2>&1 && return 0
    return 1
}

root_ro() {
    if command -v mntroot >/dev/null 2>&1; then
        mntroot ro >/dev/null 2>&1 || true
    else
        mount -o remount,ro / >/dev/null 2>&1 || true
    fi
}

remove_immutable() {
    path="$1"
    if command -v chattr >/dev/null 2>&1; then
        chattr -i "$path" >/dev/null 2>&1 || true
    fi
}

make_blocker() {
    path="$1"

    # Remove immutable only to migrate safely from older MagicAds PRO builds.
    # New installs never set immutable.
    remove_immutable "$path"
    if [ -d "$path" ] || [ -L "$path" ]; then
        rm -rf "$path" >/dev/null 2>&1 || return 1
    elif [ -e "$path" ] && [ ! -f "$path" ]; then
        rm -f "$path" >/dev/null 2>&1 || return 1
    fi

    if [ ! -f "$path" ]; then
        rm -f "$path" >/dev/null 2>&1 || true
        : > "$path" 2>/dev/null || return 1
    fi
    chmod 0444 "$path" >/dev/null 2>&1 || true

    return 0
}

write_guard() {
    mkdir -p "$PRO_DIR" || return 1
    cat > "$GUARD" <<'MAGICADS_GUARD'
#!/bin/sh
# MagicAds PRO 1.2 FINAL - low-power event driven guard

BASE="/var/local/magicads"
MARKER="$BASE/enabled"
LOG="$BASE/guard.log"
PIDFILE="$BASE/guard.pid"
DEFER_PIDFILE="$BASE/defer.pid"
EVENT_PIDFILE="$BASE/event.pid"
EVENT_FIFO="$BASE/wifi.fifo"
WIFI_PENDING="$BASE/wifi.pending"
DB="/var/local/appreg.db"
ADUNITS="/var/local/adunits"
ASSETS="/mnt/us/.assets"

log() {
    mkdir -p "$BASE" >/dev/null 2>&1 || true
    if [ -f "$LOG" ]; then
        sz="$(wc -c < "$LOG" 2>/dev/null)"
        case "$sz" in *[!0-9]*|"") sz=0 ;; esac
        if [ "$sz" -gt 131072 ]; then
            tail -n 120 "$LOG" > "$LOG.tmp" 2>/dev/null && mv -f "$LOG.tmp" "$LOG"
        fi
    fi
    echo "$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null) $*" >> "$LOG" 2>/dev/null
}

# Deliberately no immutable bit. This is safer across firmware updates.
block_adunits() {
    changed=0
    if [ -d "$ADUNITS" ] || [ -L "$ADUNITS" ]; then
        rm -rf "$ADUNITS" >/dev/null 2>&1 || return 1
        changed=1
    elif [ -e "$ADUNITS" ] && [ ! -f "$ADUNITS" ]; then
        rm -f "$ADUNITS" >/dev/null 2>&1 || return 1
        changed=1
    fi
    if [ ! -f "$ADUNITS" ]; then
        rm -f "$ADUNITS" >/dev/null 2>&1 || true
        : > "$ADUNITS" 2>/dev/null || return 1
        changed=1
    fi
    chmod 0444 "$ADUNITS" >/dev/null 2>&1 || true
    [ "$changed" -eq 1 ] && log "ADUNITS_BLOCK_REPAIRED"
    return 0
}

# .assets lives on userstore. Do not turn it into a permanent blocker file,
# because that is more invasive and could conflict with future firmware.
clean_assets() {
    if [ -d "$ASSETS" ] || [ -L "$ASSETS" ]; then
        rm -rf "$ASSETS" >/dev/null 2>&1 || { log "ASSETS_REMOVE_FAILED"; return 1; }
        log "ASSETS_REMOVED"
    fi
    return 0
}

enforce() {
    reason="${1:-manual}"
    [ -f "$MARKER" ] || return 0
    [ -f "$DB" ] || { log "DB_MISSING reason=$reason"; return 1; }
    command -v sqlite3 >/dev/null 2>&1 || { log "SQLITE_MISSING reason=$reason"; return 1; }

    dirty=0
    row_count="$(sqlite3 "$DB" 'select count(*) from properties where name = "adunit.viewable";' 2>/dev/null | tail -n 1 | tr -d '\r\n ')"
    case "$row_count" in
        ''|*[!0-9]*)
            log "DB_COUNT_INVALID reason=$reason value=${row_count:-EMPTY}"
            ;;
        0)
            # Some firmware/account states do not expose this property yet.
            # Do not INSERT an unknown-schema row; blocker remains active.
            log "DB_ROW_ABSENT reason=$reason"
            ;;
        *)
            bad_count="$(sqlite3 "$DB" 'select count(*) from properties where name = "adunit.viewable" and (value is null or lower(trim(cast(value as text))) not in ("false","0"));' 2>/dev/null | tail -n 1 | tr -d '\r\n ')"
            case "$bad_count" in
                ''|*[!0-9]*) log "DB_BAD_COUNT_INVALID reason=$reason value=${bad_count:-EMPTY}" ;;
                0) ;;
                *)
                    sqlite3 "$DB" 'pragma busy_timeout=3000; update properties set value = "false" where name = "adunit.viewable";' >/dev/null 2>&1
                    rc=$?
                    after_bad="$(sqlite3 "$DB" 'select count(*) from properties where name = "adunit.viewable" and (value is null or lower(trim(cast(value as text))) not in ("false","0"));' 2>/dev/null | tail -n 1 | tr -d '\r\n ')"
                    log "DB_FORCE_FALSE reason=$reason rows=$row_count bad_before=${bad_count:-UNKNOWN} bad_after=${after_bad:-UNKNOWN} rc=$rc"
                    [ $rc -eq 0 ] && [ "$after_bad" = "0" ] && dirty=1
                    ;;
            esac
            ;;
    esac

    before_type="none"
    [ -d "$ADUNITS" ] && before_type="dir"
    [ -f "$ADUNITS" ] && before_type="file"
    if block_adunits; then
        [ "$before_type" != "file" ] && dirty=1
    else
        log "ADUNITS_BLOCK_FAILED reason=$reason"
    fi

    if [ -d /mnt/us ]; then
        if [ -d "$ASSETS" ] || [ -L "$ASSETS" ]; then
            clean_assets && dirty=1
        fi
    fi

    [ "$dirty" -eq 1 ] && sync >/dev/null 2>&1 || true
    return 0
}

stop_children() {
    for pf in "$DEFER_PIDFILE" "$EVENT_PIDFILE"; do
        if [ -f "$pf" ]; then
            p="$(cat "$pf" 2>/dev/null)"
            case "$p" in *[!0-9]*|"") ;; *) kill "$p" >/dev/null 2>&1 || true ;; esac
            rm -f "$pf" >/dev/null 2>&1 || true
        fi
    done
    rm -f "$WIFI_PENDING" "$EVENT_FIFO" >/dev/null 2>&1 || true
}

wifi_sequence() {
    # At most one delayed repair sequence at a time. No polling.
    [ -f "$WIFI_PENDING" ] && return 0
    : > "$WIFI_PENDING" 2>/dev/null || return 0
    (
        trap 'rm -f "$WIFI_PENDING" "$DEFER_PIDFILE" >/dev/null 2>&1' EXIT HUP INT TERM
        enforce wifi_now
        sleep 15
        [ -f "$MARKER" ] || exit 0
        enforce wifi_15s
        sleep 45
        [ -f "$MARKER" ] || exit 0
        enforce wifi_60s
        sleep 120
        [ -f "$MARKER" ] || exit 0
        enforce wifi_180s
    ) &
    echo $! > "$DEFER_PIDFILE" 2>/dev/null || true
}

case "$1" in
    once)
        enforce "${2:-once}"
        exit $?
        ;;
    stop)
        stop_children
        if [ -f "$PIDFILE" ]; then
            p="$(cat "$PIDFILE" 2>/dev/null)"
            case "$p" in *[!0-9]*|"") ;; *) kill "$p" >/dev/null 2>&1 || true ;; esac
            rm -f "$PIDFILE" >/dev/null 2>&1 || true
        fi
        exit 0
        ;;
    service|*)
        ;;
esac

[ -f "$MARKER" ] || exit 0

# Avoid duplicates when multiple boot events fire.
if [ -f "$PIDFILE" ]; then
    oldpid="$(cat "$PIDFILE" 2>/dev/null)"
    case "$oldpid" in
        *[!0-9]*|"") ;;
        *) if kill -0 "$oldpid" >/dev/null 2>&1; then exit 0; fi ;;
    esac
fi

echo $$ > "$PIDFILE" 2>/dev/null
trap 'stop_children; rm -f "$PIDFILE" >/dev/null 2>&1' EXIT HUP INT TERM

log "GUARD_START pid=$$ mode=event"
enforce boot
# One short settle sequence after every boot (0/15/60/180s), then it exits.
# This catches delayed Amazon provisioning without a periodic daemon/poll loop.
wifi_sequence

# lipc-wait-event blocks inside LIPC and consumes no periodic CPU wakeups.
# cmConnected is a documented/observed Kindle Wi-Fi event used by community
# Kindle software. If unavailable, we simply keep boot protection only.
if command -v lipc-wait-event >/dev/null 2>&1 && command -v mkfifo >/dev/null 2>&1; then
    rm -f "$EVENT_FIFO" >/dev/null 2>&1 || true
    if mkfifo "$EVENT_FIFO" >/dev/null 2>&1; then
        lipc-wait-event -m com.lab126.wifid cmConnected > "$EVENT_FIFO" 2>/dev/null &
        event_pid=$!
        echo "$event_pid" > "$EVENT_PIDFILE" 2>/dev/null || true
        log "WIFI_EVENT_LISTENER_START pid=$event_pid"
        while IFS= read -r event; do
            [ -f "$MARKER" ] || break
            log "WIFI_CONNECTED"
            wifi_sequence
        done < "$EVENT_FIFO"
        kill "$event_pid" >/dev/null 2>&1 || true
        rm -f "$EVENT_PIDFILE" "$EVENT_FIFO" >/dev/null 2>&1 || true
        log "WIFI_EVENT_LISTENER_EXIT"
    else
        log "WIFI_FIFO_FAILED_BOOT_ONLY"
    fi
else
    log "WIFI_EVENT_UNAVAILABLE_BOOT_ONLY"
fi

exit 0
MAGICADS_GUARD
    chmod 0755 "$GUARD" || return 1
    return 0
}

install_upstart() {
    [ -d /etc/upstart ] || return 1
    root_rw || return 1
    cat > "$UPSTART_JOB" <<'MAGICADS_UPSTART'
# MagicAds PRO 1.2.0 FINAL - low power event driven guard
start on started lab126_gui or mounted_userstore
stop on stopping lab126_gui
exec /var/local/magicads/guard.sh service
MAGICADS_UPSTART
    rc=$?
    chmod 0644 "$UPSTART_JOB" >/dev/null 2>&1 || true
    root_ro
    [ $rc -eq 0 ] || return 1

    command -v stop >/dev/null 2>&1 && stop magicads-pro >/dev/null 2>&1 || true
    command -v start >/dev/null 2>&1 && start magicads-pro >/dev/null 2>&1 || true
    echo "Bao ve tu dong: Upstart + Wi-Fi event (neu LIPC ho tro)"
    return 0
}

install_sysv() {
    [ -d /etc/init.d ] || return 1
    [ -d /etc/rc5.d ] || [ -d /etc/rc3.d ] || return 1
    root_rw || return 1
    cat > "$SYSV_INIT" <<'MAGICADS_SYSV'
#!/bin/sh
case "$1" in
    start)
        /var/local/magicads/guard.sh service >/dev/null 2>&1 &
        ;;
    stop)
        /var/local/magicads/guard.sh stop >/dev/null 2>&1 || true
        ;;
    restart)
        /var/local/magicads/guard.sh stop >/dev/null 2>&1 || true
        /var/local/magicads/guard.sh service >/dev/null 2>&1 &
        ;;
esac
exit 0
MAGICADS_SYSV
    chmod 0755 "$SYSV_INIT"
    [ -d /etc/rc5.d ] && ln -sf "$SYSV_INIT" /etc/rc5.d/S99magicads-pro
    [ -d /etc/rc3.d ] && ln -sf "$SYSV_INIT" /etc/rc3.d/S99magicads-pro
    root_ro
    "$SYSV_INIT" restart >/dev/null 2>&1 || true
    echo "Bao ve tu dong: SysV + Wi-Fi event (neu LIPC ho tro)"
    return 0
}

remove_hooks() {
    # Stop guard first while marker still exists.
    if command -v stop >/dev/null 2>&1; then
        stop magicads-pro >/dev/null 2>&1 || true
    fi
    [ -x "$GUARD" ] && "$GUARD" stop >/dev/null 2>&1 || true
    [ -x "$SYSV_INIT" ] && "$SYSV_INIT" stop >/dev/null 2>&1 || true

    root_rw || true
    rm -f "$UPSTART_JOB" >/dev/null 2>&1 || true
    rm -f /etc/rc5.d/S99magicads-pro /etc/rc3.d/S99magicads-pro >/dev/null 2>&1 || true
    rm -f "$SYSV_INIT" >/dev/null 2>&1 || true
    if [ -f "$CRON_FILE" ]; then
        tmp="/tmp/magicads.cron.$$"
        grep -v 'MAGICADS_PRO' "$CRON_FILE" > "$tmp" 2>/dev/null || : > "$tmp"
        cat "$tmp" > "$CRON_FILE" 2>/dev/null || true
        rm -f "$tmp"
    fi
    root_ro
}

enable_pro() {
    echo "MagicAds PRO hien dang TAT."
    echo "Dang kich hoat bao ve chong quang cao..."

    mkdir -p "$PRO_DIR" || fail "Khong tao duoc thu muc MagicAds PRO."
    write_guard || fail "Khong tao duoc guard MagicAds PRO."

    cat > "$PRO_MARKER" <<EOF
MAGICADS_PRO=1
VERSION=1.2.0
GUARD_MODE=EVENT
LICENSE_ID=${LICENSE_ID:-UNKNOWN}
EXPIRE=${EXPIRE:-UNKNOWN}
SERIAL_HASH=${SERIAL_HASH:-UNKNOWN}
INSTALLED_AT=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)
EOF
    chmod 0600 "$PRO_MARKER" >/dev/null 2>&1 || true

    : > "$PRO_DIR/db_diag.log" 2>/dev/null || true
    db_diag_snapshot "before_enable"

    echo "Dang ep adunit.viewable=false..."
    db_force_false_main
    db_rc=$?
    case "$db_rc" in
        0) echo "DB: adunit.viewable = false" ;;
        2) echo "DB: chua co adunit.viewable tren trang thai firmware/account hien tai."
           echo "Guard se tu xu ly neu Amazon tao property nay; MagicAds khong chen row la vao DB." ;;
        *) fail "Khong xac minh/cap nhat duoc appreg.db." ;;
    esac

    echo "Dang khoa /var/local/adunits..."
    make_blocker "$BLOCK_ADUNITS" || fail "Khong tao duoc blocker adunits."

    echo "Dang don /mnt/us/.assets..."
    rm -rf "$BLOCK_ASSETS" >/dev/null 2>&1 || echo "Canh bao: Khong xoa duoc .assets hien tai."

    hook="none"
    if install_upstart; then
        hook="upstart"
    elif install_sysv; then
        hook="sysv"
    else
        echo "Canh bao: Khong tim thay startup hook phu hop."
        echo "Blocker van hoat dong, nhung DB guard sau boot co the khong tu khoi dong."
        echo "Khong dung cron/polling de tranh hao pin."
    fi

    "$GUARD" once >/dev/null 2>&1 || true
    sync >/dev/null 2>&1 || true

    echo "Dang xac minh DB on dinh (0s/1s/3s/10s)..."
    if db_settle_verify; then
        verify_count="$(db_adunit_count)"
        if [ "$verify_count" = "0" ]; then
            echo "DB: khong co row adunit.viewable; blocker + guard da san sang neu firmware tao lai property."
        else
            echo "DB: xac minh on dinh, tat ca adunit.viewable = false/0."
        fi
    else
        copy_db_diag_to_documents
        fail "DB bi ghi lai/khong on dinh sau 10 giay. Log: documents/MagicAds_DB.log"
    fi
    [ -f "$BLOCK_ADUNITS" ] || fail "Blocker adunits khong ton tai."
    db_diag_snapshot "enable_final"
    copy_db_diag_to_documents

    echo ""
    echo "MagicAds PRO: DA BAT"
    echo "Guard: $hook"
    echo "Quang cao da bi tat. Guard theo boot + su kien Wi-Fi; khong polling dinh ky."
    echo "Kindle se khoi dong lai sau 5 giay..."
    sleep 5
    reboot
}


upgrade_pro() {
    old_ver="$(sed -n 's/^VERSION=//p' "$PRO_MARKER" 2>/dev/null | head -n 1)"
    [ -n "$old_ver" ] || old_ver="LEGACY"
    old_license="$(sed -n 's/^LICENSE_ID=//p' "$PRO_MARKER" 2>/dev/null | head -n 1)"
    old_expire="$(sed -n 's/^EXPIRE=//p' "$PRO_MARKER" 2>/dev/null | head -n 1)"
    old_hash="$(sed -n 's/^SERIAL_HASH=//p' "$PRO_MARKER" 2>/dev/null | head -n 1)"

    echo "MagicAds PRO dang o ban $old_ver."
    echo "Dang nang cap an toan len 1.2.0 FINAL..."

    # Stop/remove legacy polling hooks first. Marker remains present so old guard
    # still fails closed while we replace files.
    remove_hooks
    mkdir -p "$PRO_DIR" || fail "Khong tao duoc thu muc MagicAds PRO."
    write_guard || fail "Khong tao duoc guard moi."

    db_force_false_main
    db_rc=$?
    case "$db_rc" in
        0|2) : ;;
        *) fail "Khong cap nhat duoc appreg.db khi nang cap." ;;
    esac
    make_blocker "$BLOCK_ADUNITS" || fail "Khong tao duoc blocker adunits khi nang cap."
    rm -rf "$BLOCK_ASSETS" >/dev/null 2>&1 || true

    hook="none"
    if install_upstart; then
        hook="upstart"
    elif install_sysv; then
        hook="sysv"
    fi

    cat > "$PRO_MARKER" <<EOF
MAGICADS_PRO=1
VERSION=1.2.0
GUARD_MODE=EVENT
LICENSE_ID=${old_license:-UNKNOWN}
EXPIRE=${old_expire:-UNKNOWN}
SERIAL_HASH=${old_hash:-UNKNOWN}
INSTALLED_AT=$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)
UPGRADED_FROM=$old_ver
EOF
    chmod 0600 "$PRO_MARKER" >/dev/null 2>&1 || true

    "$GUARD" once upgrade >/dev/null 2>&1 || true
    sync >/dev/null 2>&1 || true
    echo "MagicAds PRO: NANG CAP XONG -> 1.2.0 FINAL"
    echo "Guard: $hook"
    echo "Da bo polling 60 giay/cron. Bao ve gio theo boot + su kien Wi-Fi."
    echo "Kindle se khoi dong lai sau 5 giay..."
    sleep 5
    reboot
}

disable_pro() {
    echo "MagicAds PRO hien dang BAT."
    echo "Dang go bao ve va bat lai quang cao..."

    remove_hooks
    rm -f "$PRO_MARKER" >/dev/null 2>&1 || true

    remove_immutable "$BLOCK_ADUNITS"
    rm -f "$BLOCK_ADUNITS" >/dev/null 2>&1 || rm -rf "$BLOCK_ADUNITS" >/dev/null 2>&1 || true
    rm -f "$BLOCK_ASSETS" >/dev/null 2>&1 || rm -rf "$BLOCK_ASSETS" >/dev/null 2>&1 || true

    cnt="$(db_adunit_count)"
    if [ "$cnt" = "0" ]; then
        echo "DB: chua co adunit.viewable; khong can bat lai property."
    else
        sqlite3 "$DB" 'update properties set value = "true" where name = "adunit.viewable";' >/dev/null 2>&1 \
            || fail "Khong cap nhat duoc appreg.db."
    fi

    sync >/dev/null 2>&1 || true
    echo "MagicAds PRO: DA TAT"
    echo "Quang cao da duoc cho phep tro lai."
    echo "Kindle se khoi dong lai sau 5 giay..."
    sleep 5
    reboot
}

if [ -f "$PRO_MARKER" ]; then
    installed_ver="$(sed -n 's/^VERSION=//p' "$PRO_MARKER" 2>/dev/null | head -n 1)"
    if [ "$installed_ver" = "1.2.0" ]; then
        disable_pro
    else
        upgrade_pro
    fi
else
    enable_pro
fi
